1	// Package httpapi exposes the event timeline over HTTP.
2	package httpapi
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"io"
8		"net/http"
9		"time"
10	
11		"github.com/cocosolocoder/signalroom/internal/events"
12		"github.com/cocosolocoder/signalroom/internal/incidents"
13		"github.com/cocosolocoder/signalroom/internal/metrics"
14	)
15	
16	// maxBodyBytes bounds a single POST request body.
17	const maxBodyBytes = 16 << 20
18	
19	// Storage durably persists a batch before it becomes visible.
20	type Storage interface {
21		Append(batch []events.Event) error
22		Poisoned() bool
23	}
24	
25	type envelope struct {
26		Events json.RawMessage `json:"events"`
27	}
28	
29	// allowedEnvelopeFields is the exact set of members a POST /events body may
30	// carry.
31	var allowedEnvelopeFields = map[string]struct{}{
32		"events": {},
33	}
34	
35	// Handler wires the timeline, its durable log, and the cursor store to HTTP
36	// routes.
37	type Handler struct {
38		timeline *events.Timeline
39		log      Storage
40		cursors  CursorStore
41	
42		incidents    *incidents.Registry
43		incidentLogs IncidentStorage
44	
45		metrics    *metrics.Store
46		metricLogs MetricStorage
47	
48		mux *http.ServeMux
49	}
50	
51	// Option customizes a Handler at construction.
52	type Option func(*Handler)
53	
54	// WithIncidents enables the incident endpoints, backed by reg and its
55	// durable store.
56	func WithIncidents(reg *incidents.Registry, store IncidentStorage) Option {
57		return func(h *Handler) {
58			h.incidents = reg
59			h.incidentLogs = store
60		}
61	}
62	
63	// WithMetrics enables the metric endpoints, backed by store and its durable
64	// log.
65	func WithMetrics(store *metrics.Store, log MetricStorage) Option {
66		return func(h *Handler) {
67			h.metrics = store
68			h.metricLogs = log
69		}
70	}
71	
72	// NewHandler builds the HTTP handler for a timeline backed by log. cursors
73	// supplies the per-directory signing key and snapshot storage for paging.
74	func NewHandler(timeline *events.Timeline, log Storage, cursors CursorStore, opts ...Option) *Handler {
75		h := &Handler{timeline: timeline, log: log, cursors: cursors, mux: http.NewServeMux()}
76		for _, opt := range opts {
77			opt(h)
78		}
79		h.mux.HandleFunc("/events", h.events)
80		h.mux.HandleFunc("/alerts/preview", h.previewAlerts)
81		h.mux.HandleFunc("/events/compare", h.compareEvents)
82		h.mux.HandleFunc("/events/page", h.pageEvents)
83		if h.metrics != nil {
84			h.mux.HandleFunc("/metrics", h.metricsRoot)
85			h.mux.HandleFunc("/metrics/aggregate", h.metricsAggregate)
86		}
87		if h.incidents != nil {
88			h.mux.HandleFunc("/incidents", h.incidentsRoot)
89			h.mux.HandleFunc("/incidents/{id}", h.incidentItem)
90			h.mux.HandleFunc("/incidents/{id}/actions", h.incidentActions)
91		}
92		h.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
93			writeError(w, http.StatusNotFound, "not found")
94		})
95		return h
96	}
97	
98	func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
99		h.mux.ServeHTTP(w, r)
100	}
101	
102	func (h *Handler) unavailable() bool {
103		return h.log.Poisoned()
104	}
105	
106	func (h *Handler) events(w http.ResponseWriter, r *http.Request) {
107		switch r.Method {
108		case http.MethodPost:
109			h.postEvents(w, r)
110		case http.MethodGet:
111			h.getEvents(w, r)
112		default:
113			w.Header().Set("Allow", "GET, POST")
114			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
115		}
116	}
117	
118	func (h *Handler) postEvents(w http.ResponseWriter, r *http.Request) {
119		if h.unavailable() {
120			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
121			return
122		}
123	
124		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
125		if err != nil {
126			writeError(w, http.StatusBadRequest, "invalid JSON body")
127			return
128		}
129	
130		fields, err := decodeStrictObject(body, allowedEnvelopeFields)
131		if err != nil {
132			writeError(w, http.StatusBadRequest, "invalid JSON body")
133			return
134		}
135		input := envelope{Events: fields["events"]}
136		if len(bytes.TrimSpace(input.Events)) == 0 {
137			writeError(w, http.StatusBadRequest, "events must be a non-empty array")
138			return
139		}
140	
141		batch, err := events.DecodeBatch(input.Events)
142		if err != nil {
143			writeError(w, http.StatusBadRequest, "invalid events array")
144			return
145		}
146		if len(batch) == 0 {
147			writeError(w, http.StatusBadRequest, "events must not be empty")
148			return
149		}
150	
151		result, err := h.timeline.Ingest(batch, h.log.Append)
152		if err != nil {
153			switch {
154			case events.IsValidationError(err):
155				writeError(w, http.StatusBadRequest, err.Error())
156			case events.IsOversizeBatchError(err):
157				writeError(w, http.StatusBadRequest, err.Error())
158			case events.IsConflictError(err):
159				writeError(w, http.StatusConflict, err.Error())
160			default:
161				writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
162			}
163			return
164		}
165	
166		writeJSON(w, http.StatusOK, map[string]int{
167			"created":  result.Created,
168			"replayed": result.Replayed,
169		})
170	}
171	
172	func (h *Handler) getEvents(w http.ResponseWriter, r *http.Request) {
173		if h.unavailable() {
174			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
175			return
176		}
177	
178		values := r.URL.Query()
179		labels, err := events.ParseLabelConditions(values["label"])
180		if err != nil {
181			writeError(w, http.StatusBadRequest, err.Error())
182			return
183		}
184		query := events.Query{
185			Service:  values.Get("service"),
186			Severity: values.Get("severity"),
187			Labels:   labels,
188		}
189		if raw := values.Get("since"); raw != "" {
190			parsed, err := time.Parse(time.RFC3339Nano, raw)
191			if err != nil {
192				writeError(w, http.StatusBadRequest, "since must be an RFC3339Nano timestamp")
193				return
194			}
195			query.Since = &parsed
196		}
197		if raw := values.Get("until"); raw != "" {
198			parsed, err := time.Parse(time.RFC3339Nano, raw)
199			if err != nil {
200				writeError(w, http.StatusBadRequest, "until must be an RFC3339Nano timestamp")
201				return
202			}
203			query.Until = &parsed
204		}
205		if query.Since != nil && query.Until != nil && query.Since.After(*query.Until) {
206			writeError(w, http.StatusBadRequest, "since must not be after until")
207			return
208		}
209	
210		found := h.timeline.Query(query)
211		writeEvents(w, found)
212	}
213	
214	func writeError(w http.ResponseWriter, status int, message string) {
215		writeJSON(w, status, map[string]string{"error": message})
216	}
217	
218	func writeJSON(w http.ResponseWriter, status int, payload any) {
219		w.Header().Set("Content-Type", "application/json")
220		w.WriteHeader(status)
221		enc := json.NewEncoder(w)
222		_ = enc.Encode(payload)
223	}
224	
225	func writeEvents(w http.ResponseWriter, found []events.Event) {
226		w.Header().Set("Content-Type", "application/json")
227		w.WriteHeader(http.StatusOK)
228		if len(found) == 0 {
229			_, _ = w.Write([]byte("[]\n"))
230			return
231		}
232		if err := json.NewEncoder(w).Encode(eventsToDTOs(found)); err != nil {
233			return
234		}
235	}
236	
237	type eventDTO struct {
238		ID       string            `json:"id"`
239		Service  string            `json:"service"`
240		Severity string            `json:"severity"`
241		Message  string            `json:"message"`
242		At       time.Time         `json:"at"`
243		Labels   map[string]string `json:"labels,omitempty"`
244	}
245	
246	func eventsToDTOs(found []events.Event) []eventDTO {
247		dtos := make([]eventDTO, len(found))
248		for i, event := range found {
249			dtos[i] = eventDTO{
250				ID:       event.ID,
251				Service:  event.Service,
252				Severity: event.Severity,
253				Message:  event.Message,
254				At:       event.At,
255				Labels:   event.Labels,
256			}
257		}
258		return dtos
259	}
