295		}
296		q := events.Query{
297			Service:  values.Get("service"),
298			Severity: values.Get("severity"),
299			Labels:   labels,
300		}
301		if raw := values.Get("since"); raw != "" {
302			parsed, err := time.Parse(time.RFC3339Nano, raw)
303			if err != nil {
304				return events.Query{}, errors.New("since must be an RFC3339Nano timestamp")
305			}
306			q.Since = &parsed
307		}
308		if raw := values.Get("until"); raw != "" {
309			parsed, err := time.Parse(time.RFC3339Nano, raw)
310			if err != nil {
311				return events.Query{}, errors.New("until must be an RFC3339Nano timestamp")
312			}
313			q.Until = &parsed
314		}
315		if q.Since != nil && q.Until != nil && q.Since.After(*q.Until) {
316			return events.Query{}, errors.New("since must not be after until")
317		}
318		return q, nil
319	}
