321	// anyFilterPresent reports whether the request carries any filter parameter,
322	// which switches a continuation from "reuse the first page's filters" to
323	// "check the full filter set".
324	func anyFilterPresent(values url.Values) bool {
325		for _, name := range []string{"service", "severity", "since", "until", "label"} {
326			if _, ok := values[name]; ok {
327				return true
328			}
329		}
330		return false
331	}
332	
333	// parsePageLimit returns the limit, defaulting to defaultPageLimit when
334	// omitted. Empty, repeated, or out-of-range values are rejected.
335	func parsePageLimit(values url.Values) (int, error) {
336		vs, present := values["limit"]
337		if !present {
338			return defaultPageLimit, nil
339		}
340		if len(vs) != 1 {
341			return 0, errors.New("limit must be an integer from 1 to 1000")
342		}
343		raw := vs[0]
344		if raw == "" || !isDecimal(raw) {
345			return 0, errors.New("limit must be an integer from 1 to 1000")
346		}
347		n, err := strconv.Atoi(raw)
348		if err != nil || n < 1 || n > maxPageLimit {
349			return 0, errors.New("limit must be an integer from 1 to 1000")
350		}
351		return n, nil
352	}
353	
354	// newSnapshotID returns a random hex id for one query snapshot.
355	func newSnapshotID() (string, error) {
356		var b [16]byte
357		if _, err := rand.Read(b[:]); err != nil {
358			return "", err
359		}
360		return hex.EncodeToString(b[:]), nil
361	}
